input.content:
extends Node

signal action_rebound(action: StringName, event: InputEvent)

var _default_events: Dictionary = {}

func _ready() -> void:
	# Capture default events at startup.
	for action in InputMap.get_actions():
		if action.begins_with("ui_"):
			continue
		var events := InputMap.action_get_events(action)
		for event in events:
			if event is InputEventKey or event is InputEventJoypadButton:
				_default_events[action] = event.duplicate()
				break


func rebind_action(action: StringName, new_event: InputEvent) -> void:
	# Remove existing keyboard/joypad events.
	var events := InputMap.action_get_events(action)
	for event in events:
		if event is InputEventKey or event is InputEventJoypadButton:
			InputMap.action_erase_event(action, event)
	InputMap.action_add_event(action, new_event)
	action_rebound.emit(action, new_event)


func get_action_event(action: StringName) -> InputEvent:
	var events := InputMap.action_get_events(action)
	for event in events:
		if event is InputEventKey or event is InputEventJoypadButton:
			return event
	return null


func save_to_file(path: String = "user://input_map.cfg") -> void:
	var config := ConfigFile.new()
	for action in InputMap.get_actions():
		if action.begins_with("ui_"):
			continue
		var event := get_action_event(action)
		if event is InputEventKey:
			config.set_value(action, "type", "key")
			config.set_value(action, "keycode", event.keycode)
		elif event is InputEventJoypadButton:
			config.set_value(action, "type", "joypad")
			config.set_value(action, "button", event.button_index)
	config.save(path)


func load_from_file(path: String = "user://input_map.cfg") -> bool:
	if not FileAccess.file_exists(path):
		return false
	var config := ConfigFile.new()
	var error := config.load(path)
	if error != OK:
		return false
	for section in config.get_sections():
		if not InputMap.has_action(section):
			continue
		var type = config.get_value(section, "type")
		if type == "key":
			var event := InputEventKey.new()
			event.keycode = config.get_value(section, "keycode")
			rebind_action(section, event)
		elif type == "joypad":
			var event := InputEventJoypadButton.new()
			event.button_index = config.get_value(section, "button")
			rebind_action(section, event)
	return true


func reset_to_defaults() -> void:
	for action in _default_events:
		rebind_action(action, _default_events[action])

extends Button

@export var action_name: StringName

var _listening: bool = false


func _ready() -> void:
	pressed.connect(_on_pressed)
	_update_label()


func _update_label() -> void:
	text = "%s: %s" % [action_name, _get_action_text()]


func _get_action_text() -> String:
	if _listening:
		return "..."
	var event := InputRemapper.get_action_event(action_name)
	return event.as_text() if event else "None"


func _on_pressed() -> void:
	_listening = true
	_update_label()


func _unhandled_input(event: InputEvent) -> void:
	if not _listening:
		return
	if event is InputEventKey and event.pressed:
		_accept_event(event)
	elif event is InputEventJoypadButton and event.pressed:
		_accept_event(event)


func _accept_event(event: InputEvent) -> void:
	_listening = false
	InputRemapper.rebind_action(action_name, event)
	_update_label()
